// Parses top-level metadata from every incoming item.
// Expects each item.json to contain the YAML string at .data (or .body for Full Response).

const inItems = $input.all();

return inItems.map((item, idx) => {
  const yamlStr =
    typeof item.json?.data === 'string' ? item.json.data :
    typeof item.json?.body === 'string' ? item.json.body :
    (typeof item.json === 'string' ? item.json : null);

  if (typeof yamlStr !== 'string') {
    throw new Error(`Item ${idx}: expected YAML string at .data (or .body), got ${typeof yamlStr}`);
  }

  // Only the TOP-LEVEL metadata block
  const metaBlockMatch = yamlStr.match(/(^|\n)metadata:\s*\n([\s\S]*?)(?=\n\S|\n$)/m);
  if (!metaBlockMatch) throw new Error(`Item ${idx}: top-level 'metadata:' block not found`);
  const meta = metaBlockMatch[2];

  const nameMatch = meta.match(/^\s*name:\s*([A-Za-z0-9.-]+)/m);
  const genMatch  = meta.match(/^\s*generateName:\s*([A-Za-z0-9.-]+)-?/m);
  const nsMatch   = meta.match(/^\s*namespace:\s*([A-Za-z0-9-]+)/m);

  const jobName      = nameMatch ? nameMatch[1] : null;
  const generateName = genMatch  ? genMatch[1] : null;
  const namespace    = nsMatch   ? nsMatch[1] : (item.json.namespace || 'n8n');

  if (!jobName && !generateName) {
    throw new Error(`Item ${idx}: neither metadata.name nor metadata.generateName found`);
  }

  // Try to infer tool if not set upstream
  const tool = item.json.tool || (jobName ? jobName.split('-')[0] : undefined);

  return {
    json: {
      tool,
      jobName,
      generateName,   // present if YAML uses generateName
      namespace,
      yaml: yamlStr
    }
  };
