// --- INPUTS ---
// Webhook shape: $json.body contains payload; else use $json
const src = $json?.body && typeof $json.body === 'object' ? $json.body : $json;

// Defaults
const DEFAULTS = {
  owner:     "cray9741",
  repo:      "ScanJobs",
  branch:    "main",
  namespace: "n8n",
};

// Pull fields (fallback to defaults)
let owner     = src.owner     ?? DEFAULTS.owner;
let repo      = src.repo      ?? DEFAULTS.repo;
let branch    = src.branch    ?? DEFAULTS.branch;
let namespace = src.namespace ?? DEFAULTS.namespace;

// Accept both `tool` and/or `tools` (string or array). Coerce to array.
function coerceTools(v1, v2){
  let parts = [];
  const push = (v) => {
    if (Array.isArray(v)) parts.push(...v);
    else if (typeof v === 'string') {
      // split on comma or whitespace, trim, drop empties
      parts.push(...v.split(/[,\s]+/).map(s => s.trim()).filter(Boolean));
    }
  };
  push(v1); push(v2);
  // unique + lowercase
  parts = [...new Set(parts.map(t => String(t).toLowerCase()))];
  // treat "all" specially
  const wantsAll = parts.length === 0 || parts.includes('all');
  return { wantsAll, tools: wantsAll ? [] : parts };
}
const { wantsAll, tools } = coerceTools(src.tool, src.tools);

// Normalize owner/repo if repo is "owner/repo" or a full URL
function normalizeOwnerRepo(ownerVal, repoVal){
  let o = ownerVal || "";
  let r = (repoVal || "").trim();
  if (/^https?:\/\/(www\.)?github\.com\//i.test(r)) {
    const path = r.replace(/^https?:\/\/(www\.)?github\.com\//i, "").replace(/\.git$/i, "");
    const parts = path.split("/").filter(Boolean);
    if (parts.length >= 2) { o = parts[0]; r = parts[1]; }
  } else if (!o && r.includes("/")) {
    const parts = r.split("/").filter(Boolean);
    if (parts.length >= 2) { o = parts[0]; r = parts[1]; }
  }
  if (!o || !r) throw new Error(`Missing owner/repo after normalization (owner='${o}', repo='${r}').`);
  return { owner: o, repo: r };
}
({ owner, repo } = normalizeOwnerRepo(owner, repo));

// Build list URL for "deploy all" mode
const scansListUrl = `https://api.github.com/repos/${owner}/${repo}/contents/Scans?ref=${encodeURIComponent(branch)}`;

return [{
  json: {
    owner, repo, branch, namespace,
    deployAll: wantsAll,        // true → list Scans/ and fan out
    tools,                      // explicit list (if any)
    scansListUrl
  }
}];

// This node receives MANY merged items (config + one folder each)
const items = $input.all();

const out = [];
for (const it of items) {
  const cfg = {
    owner: it.json.owner, repo: it.json.repo, branch: it.json.branch,
    namespace: it.json.namespace, deployAll: it.json.deployAll,
    tools: Array.isArray(it.json.tools) ? it.json.tools : []
  };
  const folder = String(it.json.name || "").toLowerCase(); // folder name under Scans/

  const include = cfg.deployAll || cfg.tools.includes(folder);
  if (!include) continue;

  out.push({
    json: {
      owner: cfg.owner, repo: cfg.repo, branch: cfg.branch,
      namespace: cfg.namespace, tool: folder,
      // convenience URL for next step
      fetchUrl: `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents/Scans/${folder}/job.yaml?ref=${encodeURIComponent(cfg.branch)}`
    }
  });
}

if (!out.length) throw new Error("No tools selected. Provide tool(s) or ensure Scans/ has subfolders.");
return out;
